  const prepAct = ["prep_summary","prep_queue","prep_set","prep_contact","li_save","li_sent","style_samples","autosweep"].includes(action);
  if (needTarget && !String(b.target || '').trim()) throw new Error('target obligatorio (nombre, dominio, id o URL de LinkedIn del prospecto)');
  const sb = 'https://uwquwjmiofixzugttals.supabase.co/rest/v1/';
