    cands: sb + 'prospect_candidates?status=in.(in_ghl,accepted,contacted,discarded)&select=id,company_name,domain,website,status,band,priority_score,source_name,ghl_contact_id,ghl_opportunity_id,ghl_stage,last_contact_channel,last_contact_at,next_action_at,channel_state,canonical,created_at&order=priority_score.desc&limit=500',
