function liConfirmHash(parts) { let h = 0x811c9dc5; const s = parts.join('\u0001'); for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return h.toString(16).padStart(8, '0'); }

