  if (li && !prepLinkedinUrl(li)) return fail('linkedin_invalido', 'Ese enlace no es un perfil personal de LinkedIn (https://www.linkedin.com/in/…).');
  const canon = cand.canonical || {};
  const contact = { ...(canon.contact || {}) };
