    effects: prev && prev.prepared_at ? [] : [{ type: 'gateway_act', act: { type: 'add_note', note: 'LINKEDIN POR ENVIAR (manual) · Perfil: ' + li.profile_url + ' · INVITACIÓN: «' + invitation + '» · MENSAJE tras conectar: «' + message + '».' } }] };
